function esc(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const webhook = $('Webhook').first().json;
const body = webhook.body && typeof webhook.body === 'object' ? webhook.body : webhook;
const binary = $input.first().binary || {};

const nombres = String(body.nombres || '').trim();
const apellidos = String(body.apellidos || '').trim();
const correo = String(body.correo || '').trim();
const es = String(body.idioma || 'es').startsWith('es');
const nombre = esc([nombres, apellidos].filter(Boolean).join(' ') || (es ? 'hola' : 'there'));

const html = es
  ? `<p>Hola ${nombre},</p><p>Gracias por solicitar información en ALLPATEK. Adjuntamos la propuesta técnica.</p><p>Si quieres revisar una parcela o agendar una llamada, responde a este correo.</p><p>Equipo ALLPATEK</p>`
  : `<p>Hello ${nombre},</p><p>Thank you for requesting information from ALLPATEK. The technical proposal is attached.</p><p>Reply to this email if you want to review a plot or schedule a call.</p><p>ALLPATEK team</p>`;

return [{
  json: {
    correo,
    nombres,
    apellidos,
    telefono: String(body.telefono || '').trim(),
    asunto: es ? 'Tu propuesta técnica ALLPATEK' : 'Your ALLPATEK technical proposal',
    html,
  },
  binary,
}];
